  ["9bf997ed68330bc1"] = { "Parla con la sentinella Onaeya all'⟦Maestra's Post=Accampamento di Maestra⟧, a ⟦Ashenvale=Valtetra⟧: farà in modo che tu riceva la giusta ricompensa per il coraggio dimostrato oggi.", "." },
